"""Literal independent expected coordinates, not generated by the transform."""
import json
import math
import unittest
from pathlib import Path

from annotation.geometry import GeometryError, ImageBinding, OriginalBox, Transform, invert_affine

ROOT = Path(__file__).resolve().parents[1]
IMAGE = ImageBinding(asset_id="asset-original",width=100,height=60,sha256="1"*64)


class GeometryTests(unittest.TestCase):
    def close(self, actual, expected):
        self.assertEqual(len(actual),len(expected))
        for a,e in zip(actual,expected):
            self.assertTrue(math.isclose(a,e,rel_tol=0,abs_tol=1e-9),(actual,expected))

    def test_hand_calculated_points_and_four_corner_boxes(self):
        table = json.loads((ROOT/"tests/fixtures/a01/geometry-hand-calculated.json").read_text())
        for case in table["cases"]:
            with self.subTest(case=case["name"]):
                transform = Transform(IMAGE,**case["config"])
                processed = transform.processed_binding("asset-processed","2"*64)
                self.assertEqual(list(transform.output_size),case["output_size"])
                self.close(transform.forward_point(case["point"],IMAGE),case["expected_point"])
                self.close(transform.inverse_point(case["expected_point"],processed,processed),case["point"])
                box = OriginalBox(image=IMAGE,bbox=[float(v) for v in case["box"]])
                self.close(transform.forward_box(box,processed).bbox,case["expected_box"])
                expected_box = OriginalBox(image=processed,bbox=[float(v) for v in case["expected_box"]])
                self.close(transform.inverse_box(expected_box,processed).bbox,case["box"])

    def test_boundaries_are_not_pixel_center_indices(self):
        transform = Transform(IMAGE,rotation_degrees=90)
        self.close(transform.forward_point((0,0),IMAGE),(60,0))
        self.close(transform.forward_point((100,60),IMAGE),(0,100))
        self.close(transform.forward_point((0.5,0.5),IMAGE),(59.5,0.5))
        # An origin-only rotation gives (-10,20); counterclockwise gives (10,80).
        self.close(transform.forward_point((20,10),IMAGE),(50,20))

    def test_invalid_transforms_are_rejected(self):
        cases = [dict(scale=(0,1)),dict(scale=(-1,1)),dict(scale=(float("nan"),1)),
                 dict(scale=(1,float("inf"))),dict(scale=(1e-300,1e-300)),dict(scale=(1e308,1e308)),
                 dict(crop=(10,5,10,20)),dict(crop=(-1,0,10,10)),dict(crop=(0,0,101,60)),
                 dict(crop=(0,0,float("inf"),60)),dict(scale=(1.001,1)),dict(scale=(1.000000000005,1)),
                 dict(rotation_degrees=45),dict(rotation_degrees=float("nan")),dict(rotation_degrees=True),
                 dict(padding=(-1,0,0,0)),dict(padding=(0.5,0,0,0)),dict(padding=(0,0,float("inf"),0)),
                 dict(spec_version="unconfirmed")]
        for config in cases:
            with self.subTest(config=config), self.assertRaises(GeometryError):
                Transform(IMAGE,**config)

    def test_unknown_transform_types_and_ambiguous_contract_rejected(self):
        for config in (dict(matrix=(1,0,0,0,0,0)),dict(perspective=True),dict(reflection=True)):
            with self.subTest(config=config),self.assertRaises(TypeError):
                Transform(IMAGE,**config)
        with self.assertRaisesRegex(GeometryError,"AMBIGUOUS_SPEC"):
            Transform.from_contract_crop_transform({"offset_x":10})

    def test_singular_and_nonfinite_matrix_rejected(self):
        for matrix in ((1,2,3,2,4,6),(1,0,0,0,0,0),(math.nan,0,0,0,1,0),(1,0,0,0,math.inf,0)):
            with self.subTest(matrix=matrix),self.assertRaises(GeometryError):
                invert_affine(matrix)
        self.close(invert_affine((2,0,4,0,3,9)),(0.5,0,-2,0,1/3,-3))

    def test_binding_conflicts_in_both_directions(self):
        transform = Transform(IMAGE)
        processed = transform.processed_binding("asset-processed","2"*64)
        for key,value in (("asset_id","asset-other"),("width",101),("height",61),("sha256","3"*64)):
            data = IMAGE.model_dump()
            data[key] = value
            bad = ImageBinding.model_validate(data)
            with self.subTest(key=key),self.assertRaises(GeometryError):
                transform.forward_point((1,1),bad)
            data = processed.model_dump()
            data[key] = value
            bad = ImageBinding.model_validate(data)
            with self.subTest(inverse=key),self.assertRaises(GeometryError):
                transform.inverse_point((1,1),bad,processed)
        with self.assertRaises(GeometryError):
            transform.forward_box(OriginalBox(image=processed,bbox=[1.,1.,2.,2.]),processed)
        with self.assertRaises(GeometryError):
            transform.inverse_box(OriginalBox(image=IMAGE,bbox=[1.,1.,2.,2.]),processed)

    def test_invalid_points_boxes_and_padding_are_not_clipped(self):
        transform = Transform(IMAGE,crop=(10,5,50,25),padding=(3,7,11,13))
        processed = transform.processed_binding("asset-processed","2"*64)
        for point in ((0,0),(9.99999999999,5),(10,26),(math.nan,1),(1,math.inf)):
            with self.subTest(point=point),self.assertRaises(GeometryError):
                transform.forward_point(point,IMAGE)
        for bbox in ((10,5,9,6),(10,5,10,6),(-0.00000000001,5,20,6),(10,5,101,6),
                     (10,5,math.nan,6),(10,5,20,math.inf),(9,5,20,6)):
            with self.subTest(bbox=bbox),self.assertRaises(GeometryError):
                transform.forward_box(dict(image=IMAGE.model_dump(),bbox=list(bbox)),processed)
        for point in ((0,0),(2.99999999999,7),(54,8),(1,math.nan)):
            with self.subTest(padding=point),self.assertRaises(GeometryError):
                transform.inverse_point(point,processed,processed)
        with self.assertRaises(GeometryError):
            transform.inverse_box(OriginalBox(image=processed,bbox=[0.,0.,4.,8.]),processed)

    def test_finite_fractional_scale_and_negative_quarter_turn(self):
        transform = Transform(IMAGE,scale=(0.5,1.5),rotation_degrees=-90)
        self.assertEqual(transform.output_size,(90,50))
        self.close(transform.forward_point((20,10),IMAGE),(15,40))


if __name__ == "__main__":
    unittest.main()
